import { useState } from 'react';
import { Button, Field, Modal } from '../ui';
import { downloadReceiptPdf } from '../../lib/api';
import { fmtDateTime, inr, totals } from '../../lib/format';
import type { FeeStatement, Payment, Student } from '../../types';

interface Props { student: Student; statement: FeeStatement; payment: Payment; onClose: () => void }

/** On-screen preview. The downloadable PDF is generated by the backend so it matches the database record. */
export default function FeeReceipt({ student, statement, payment, onClose }: Props) {
  const t = totals(statement);
  const [err, setErr] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const download = async () => {
    setBusy(true); setErr(null);
    try { await downloadReceiptPdf(payment.id, `Fee-Receipt-${payment.receiptNo ?? payment.id}.pdf`); }
    catch (e) { setErr(e instanceof Error ? e.message : 'Download failed.'); }
    finally { setBusy(false); }
  };
  return (
    <Modal label="Fee receipt" onClose={onClose} maxWidth="max-w-[640px]">
      <div className="p-7">
        <div className="flex items-start justify-between gap-3 border-b-2 border-navy pb-3.5">
          <div className="flex items-center gap-3">
            <div className="flex h-11 w-11 items-center justify-center rounded-lg border border-dashed border-[#B9C2D3] text-[11px] text-label">LOGO</div>
            <div><div className="text-base font-semibold">Pune Institute of Computer Technology</div><div className="text-xs text-muted">Fee Receipt · Academic year {payment.academicYear}</div></div>
          </div>
          <div className="text-right"><div className="text-xs text-muted">Receipt no.</div><div className="font-semibold">{payment.receiptNo ?? '—'}</div></div>
        </div>
        {payment.isTest && <div className="mt-2.5 inline-block rounded bg-warn-bg px-2.5 py-[3px] text-xs font-semibold text-warn-ink">TEST MODE RECEIPT · NOT A REAL PAYMENT</div>}
        <div className="mt-3.5 grid grid-cols-[repeat(auto-fit,minmax(160px,1fr))] gap-x-5 gap-y-2.5">
          <Field label="Student" value={student.name} />
          <Field label="Student no." value={student.studentNo} />
          <Field label="Department / course" value={`${student.department} · ${student.program}`} />
          <Field label="Payment date" value={fmtDateTime(payment.date)} />
          <Field label="Reference ID" value={payment.referenceId} />
          <Field label="Method · Status" value={`${payment.method} · Paid`} />
        </div>
        <div className="mt-3.5">
          {statement.components.map((c) => <div key={c.id} className="flex justify-between border-t border-rule py-2"><span>{c.name}</span><span>{inr(c.amount)}</span></div>)}
          <div className="flex justify-between border-t-2 border-ink py-2.5 font-semibold"><span>Total academic fee</span><span>{inr(t.total)}</span></div>
          <div className="flex justify-between py-1.5 font-semibold text-ok"><span>Amount paid (this transaction)</span><span>{inr(payment.amount)}</span></div>
          <div className="flex justify-between py-1.5"><span>Total paid to date</span><span>{inr(t.paid)}</span></div>
          <div className="flex justify-between py-1.5"><span>Outstanding balance</span><span>{inr(t.outstanding)}</span></div>
        </div>
        {err && <div className="mt-3 rounded-lg bg-err-bg px-3 py-2 text-err-ink">{err}</div>}
        <div className="mt-4 flex flex-wrap gap-2.5">
          <Button onClick={download} disabled={busy}>{busy ? 'Preparing PDF…' : 'Download PDF'}</Button>
          <Button variant="secondary" onClick={onClose}>Return to Fee Structure</Button>
        </div>
      </div>
    </Modal>
  );
}
